/**
 * @zh 用于CCheckbox.Group.Options的Props。扩展自CheckboxGroupProps.options
 */
export type CCheckboxGroupOption<T> = T | {
  /**
   * @zh checkbox的显示文本
   * @en checkbox label
   */
  label: ReactNode;
  /**
   * @zh 双行单选组的第二行展示文字
   * @en checkbox description
   */
  description?: ReactNode;
  /**
   * @zh 图标配置
   * @en icon config
   */
  icon?: ReactNode;
  /**
   * @zh value
   * @en value
   */
  value: T;
  /**
   * @zh 禁用按钮
   * @en disable button
   */
  disabled?: boolean;
  /**
   * @zh 角标
   * @en tag
   */
  tag?: ReactNode;
  /**
   * @zh 角标的样式配置
   * @en tag cssproperties config
   */
  CTagProps?: Omit<CTagProps, 'shape' | 'type'>;
  /**
   * @zh Arco Popover 属性透传
   * @en Arco Popover props
   */
  arcoPopoverProps?: PopoverProps;
};

