import React from 'react';
import { Button, CCheckbox } from '@cloud-materials/common';
import type { CCheckboxGroupOption } from '../interface';

const CCheckboxGroup = CCheckbox.Group;

const statusOptions: CCheckboxGroupOption<string>[] = [
  {
    value: 'Beijing',
    label: '公共镜像',
  },
  {
    value: 'Beijing2',
    label: '公共镜像',
  },
  {
    value: 'Beijing3',
    label: '公共镜像',
    disabled: true,
  },
  {
    value: 'Beijing4',
    label: '公共镜像公共镜像',
  },
];

export default () => {
  return (
    <>
      <h3>可以通过传入函数类型的 children 来自定义渲染单选节点。</h3>
      <CCheckboxGroup defaultValue={['Beijing']}>
        {statusOptions.map((p: { value: string; label: string }) => (
          <CCheckbox value={p.value} key={p.value}>
            {({ checked }) => {
              return (
                <Button key={p.value} shape="round" type={checked ? 'primary' : 'default'}>
                  {p.label}
                </Button>
              );
            }}
          </CCheckbox>
        ))}
      </CCheckboxGroup>
    </>
  );
};
